export function ratio_distance_delta(
  photo:number,
  old_bare:number,
  old_blades:number,
  new_bare:number,
  new_blades:number
):number {
  return (Math.abs(new_blades-photo)-Math.abs(new_bare-photo))
    -(Math.abs(old_blades-photo)-Math.abs(old_bare-photo));
}

// 发布保持1；只在受控试验构建中改为0.55。
const CAPTURE_BLADE_SHADE_GAIN:number = 1;

function setCaptureBladeLighting(
  color:THREE.Color,
  v:number,
  shade:number,
  shadeGain:number
):void {
  if (!(shadeGain >= 0.55 && shadeGain <= 1)) {
    throw new RangeError('blade shade gain must be in [0.55,1]');
  }
  if (!(shade >= 0 && shade <= 1)) {
    throw new RangeError('captureLight must return a value in [0,1]');
  }
  color.setRGB(
    v*(1-(1-shadeGain*(1-.82885))*shade),
    v*(1-(1-shadeGain*(1-.78591))*shade),
    v*(.94-(.94-shadeGain*(.94-.69130))*shade)
  );
}

将原instanceColor.setRGB(...)整句替换为：
setCaptureBladeLighting(instanceColor,v,shade,CAPTURE_BLADE_SHADE_GAIN);
mesh.setColorAt(q,instanceColor);

gain=1在代数上恢复原式；shade=0时任意试验增益均保持原阳区端点；shade=1时仅把原草叶阴区RGB端点乘gain。0.55是承接前序试验的工程消融参数，不是实测置信度，也不是对底材入射光的完整修改。此补丁不接入尚未确认的referenceShadowLinearRGB，不修改底材材质、不改变法线或几何，也不同时应用前序全局阴区增益，否则无法隔离归因。
